#!/usr/bin/env python3
"""
American Express (AXP) Historical Stock Performance Report Generator
Produces a self-contained HTML report with embedded Chart.js visualizations.
"""

import pandas as pd
import numpy as np
import json
import os
from datetime import datetime

# ── Load Data ──────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'], utc=True)
df = df.sort_values('Date').reset_index(drop=True)
df['Year'] = df['Date'].dt.year
df['Decade'] = (df['Year'] // 10) * 10

# ── KPI Calculations ──────────────────────────────────────────────────────
first_close = df['Close'].iloc[0]
last_close = df['Close'].iloc[-1]
first_date = df['Date'].iloc[0]
last_date = df['Date'].iloc[-1]
years_span = (last_date - first_date).days / 365.25

cumulative_return = (last_close - first_close) / first_close * 100
cagr = ((last_close / first_close) ** (1 / years_span) - 1) * 100

# Daily returns & volatility
df['Daily_Return'] = df['Close'].pct_change()
daily_vol = df['Daily_Return'].dropna().std()
annualized_vol = daily_vol * np.sqrt(252) * 100

# Max drawdown
df['Cummax'] = df['Close'].cummax()
df['Drawdown'] = (df['Close'] - df['Cummax']) / df['Cummax'] * 100
max_dd = df['Drawdown'].min()
max_dd_idx = df['Drawdown'].idxmin()
max_dd_date = df.loc[max_dd_idx, 'Date']
max_dd_peak_idx = df.loc[:max_dd_idx, 'Close'].idxmax()
max_dd_peak_date = df.loc[max_dd_peak_idx, 'Date']
max_dd_trough_price = df.loc[max_dd_idx, 'Close']
max_dd_peak_price = df.loc[max_dd_peak_idx, 'Close']

# Total dividends
total_dividends = df['Dividends'].sum()

# Stock splits
splits = df[df['Stock Splits'] != 0.0][['Date', 'Stock Splits']].copy()

# Dividend events
div_events = df[df['Dividends'] != 0.0][['Date', 'Close', 'Dividends']].copy()
div_events['Yield_Pct'] = (div_events['Dividends'] / div_events['Close']) * 100

# ── All-time high / low ──────────────────────────────────────────────────
ath_idx = df['Close'].idxmax()
ath_price = df.loc[ath_idx, 'Close']
ath_date = df.loc[ath_idx, 'Date']

atl_idx = df['Close'].idxmin()
atl_price = df.loc[atl_idx, 'Close']
atl_date = df.loc[atl_idx, 'Date']

# ── Bull/Bear Phase Detection ────────────────────────────────────────────
# A bear market = drawdown >= 20%, bull = recovery to new high
# Identify major drawdown episodes (>= 15%)
def find_drawdown_episodes(df, threshold=-15):
    episodes = []
    in_drawdown = False
    peak_idx = 0
    peak_price = df['Close'].iloc[0]

    for i in range(len(df)):
        price = df['Close'].iloc[i]
        if price >= peak_price:
            peak_price = price
            peak_idx = i

        dd = (price - peak_price) / peak_price * 100
        if dd <= threshold and not in_drawdown:
            in_drawdown = True
            trough_idx = i
            trough_dd = dd
        elif in_drawdown:
            if dd < trough_dd:
                trough_idx = i
                trough_dd = dd
            if price >= peak_price:  # recovered
                episodes.append({
                    'peak_date': df['Date'].iloc[peak_idx],
                    'trough_date': df['Date'].iloc[trough_idx],
                    'recovery_date': df['Date'].iloc[i],
                    'peak_price': df['Close'].iloc[peak_idx],
                    'trough_price': df['Close'].iloc[trough_idx],
                    'drawdown_pct': trough_dd,
                    'duration_days': (df['Date'].iloc[trough_idx] - df['Date'].iloc[peak_idx]).days,
                    'recovery_days': (df['Date'].iloc[i] - df['Date'].iloc[trough_idx]).days,
                })
                in_drawdown = False
                peak_price = price
                peak_idx = i

    # If still in drawdown at end
    if in_drawdown:
        episodes.append({
            'peak_date': df['Date'].iloc[peak_idx],
            'trough_date': df['Date'].iloc[trough_idx],
            'recovery_date': None,
            'peak_price': df['Close'].iloc[peak_idx],
            'trough_price': df['Close'].iloc[trough_idx],
            'drawdown_pct': trough_dd,
            'duration_days': (df['Date'].iloc[trough_idx] - df['Date'].iloc[peak_idx]).days,
            'recovery_days': None,
        })

    return episodes

major_episodes = find_drawdown_episodes(df, threshold=-20)

# ── Decade-by-Decade Analysis ────────────────────────────────────────────
decades = [1970, 1980, 1990, 2000, 2010, 2020]
decade_stats = []

for i, dec in enumerate(decades):
    dec_df = df[df['Decade'] == dec]
    if len(dec_df) == 0:
        continue

    dec_first = dec_df['Close'].iloc[0]
    dec_last = dec_df['Close'].iloc[-1]
    dec_return = (dec_last - dec_first) / dec_first * 100

    dec_years = (dec_df['Date'].iloc[-1] - dec_df['Date'].iloc[0]).days / 365.25
    dec_cagr = ((dec_last / dec_first) ** (1 / dec_years) - 1) * 100 if dec_years > 0 else 0

    dec_vol = dec_df['Daily_Return'].dropna().std() * np.sqrt(252) * 100

    dec_dd = ((dec_df['Close'] - dec_df['Close'].cummax()) / dec_df['Close'].cummax() * 100).min()

    dec_div = dec_df['Dividends'].sum()
    dec_div_count = (dec_df['Dividends'] != 0).sum()

    dec_volume = dec_df[dec_df['Volume'] > 0]['Volume'].mean() if (dec_df['Volume'] > 0).any() else 0

    decade_stats.append({
        'decade': f"{dec}s",
        'start_price': round(dec_first, 2),
        'end_price': round(dec_last, 2),
        'total_return_pct': round(dec_return, 1),
        'cagr_pct': round(dec_cagr, 1),
        'annualized_vol_pct': round(dec_vol, 1),
        'max_drawdown_pct': round(dec_dd, 1),
        'total_dividends': round(dec_div, 4),
        'dividend_payments': int(dec_div_count),
        'avg_daily_volume': int(dec_volume) if dec_volume else 0,
    })

# ── Sub-period CAGR ──────────────────────────────────────────────────────
sub_periods = [
    ("1972–1985", "1972-01-01", "1985-12-31"),
    ("1986–1999", "1986-01-01", "1999-12-31"),
    ("2000–2009", "2000-01-01", "2009-12-31"),
    ("2010–2019", "2010-01-01", "2019-12-31"),
    ("2020–2026", "2020-01-01", "2099-12-31"),
]

sub_cagrs = []
for label, start, end in sub_periods:
    mask = (df['Date'] >= pd.Timestamp(start, tz='UTC')) & (df['Date'] <= pd.Timestamp(end, tz='UTC'))
    sub_df = df[mask]
    if len(sub_df) < 2:
        continue
    sp = sub_df['Close'].iloc[0]
    ep = sub_df['Close'].iloc[-1]
    sy = (sub_df['Date'].iloc[-1] - sub_df['Date'].iloc[0]).days / 365.25
    sc = ((ep / sp) ** (1 / sy) - 1) * 100 if sy > 0 else 0
    sub_cagrs.append({
        'label': label,
        'start_price': round(sp, 2),
        'end_price': round(ep, 2),
        'cagr_pct': round(sc, 1),
        'total_return_pct': round((ep - sp) / sp * 100, 1),
    })

# ── Volume Analysis ──────────────────────────────────────────────────────
df_vol = df[df['Volume'] > 0].copy()
# Monthly average volume
df_vol['Month'] = df_vol['Date'].dt.to_period('M')
monthly_vol = df_vol.groupby('Month')['Volume'].mean()
# Yearly average volume
df_vol['VolYear'] = df_vol['Date'].dt.year
yearly_vol = df_vol.groupby('VolYear')['Volume'].mean()

# Volume spikes (> 3x rolling 50-day average)
df_vol['Vol_MA50'] = df_vol['Volume'].rolling(50, min_periods=10).mean()
df_vol['Vol_Ratio'] = df_vol['Volume'] / df_vol['Vol_MA50']
vol_spikes = df_vol[df_vol['Vol_Ratio'] > 3].copy()
top_vol_spikes = vol_spikes.nlargest(10, 'Vol_Ratio')[['Date', 'Close', 'Volume', 'Vol_Ratio']]

# ── Dividend Analysis ────────────────────────────────────────────────────
# Annual dividend totals
div_events_copy = div_events.copy()
div_events_copy['DivYear'] = div_events_copy['Date'].dt.year
annual_div = div_events_copy.groupby('DivYear')['Dividends'].sum()

# Dividend yield trend (annual)
yearly_close = df.groupby('Year')['Close'].last()
div_yield_annual = {}
for yr in annual_div.index:
    if yr in yearly_close.index and yearly_close[yr] > 0:
        div_yield_annual[yr] = (annual_div[yr] / yearly_close[yr]) * 100

# ── Chart Data Preparation ───────────────────────────────────────────────
# Monthly resampled close for main price chart
df_monthly = df.set_index('Date').resample('MS')['Close'].first().reset_index()
df_monthly.columns = ['Date', 'Close']

# For drawdown chart - monthly
df_dd_monthly = df.set_index('Date').resample('MS').agg({'Close': 'last', 'Drawdown': 'last'}).reset_index()

# Volume chart data - monthly average
vol_monthly_data = df_vol.set_index('Date').resample('MS')['Volume'].mean().reset_index()
vol_monthly_data.columns = ['Date', 'Volume']

# ── JSON Data for Charts ─────────────────────────────────────────────────
price_dates = [d.strftime('%Y-%m') for d in df_monthly['Date']]
price_values = [round(v, 2) for v in df_monthly['Close']]

dd_dates = [d.strftime('%Y-%m') for d in df_dd_monthly['Date']]
dd_values = [round(v, 2) for v in df_dd_monthly['Drawdown']]

vol_dates = [d.strftime('%Y-%m') for d in vol_monthly_data['Date']]
vol_values = [int(v) for v in vol_monthly_data['Volume']]

# Decade comparison chart data
dec_labels = [d['decade'] for d in decade_stats]
dec_returns = [d['total_return_pct'] for d in decade_stats]
dec_vol_chart = [d['annualized_vol_pct'] for d in decade_stats]
dec_dd_chart = [abs(d['max_drawdown_pct']) for d in decade_stats]
dec_cagr_chart = [d['cagr_pct'] for d in decade_stats]

# Dividend yield chart
div_yield_years = sorted(div_yield_annual.keys())
div_yield_vals = [round(div_yield_annual[y], 2) for y in div_yield_years]

# ── Top Volume Spikes for Table ──────────────────────────────────────────
vol_spike_rows = ""
for _, row in top_vol_spikes.iterrows():
    vol_spike_rows += f"""
        <tr>
