      legend: {{ display: false }},
      tooltip: {{
        callbacks: {{
          label: ctx => '$' + ctx.parsed.y.toFixed(2)
        }}
      }}
    }},
    scales: {{
      x: {{
        ticks: {{ maxTicksLimit: 12, maxRotation: 0 }},
        grid: {{ display: false }}
      }},
      y: {{
        ticks: {{ callback: v => '$' + v }},
        grid: {{ color: 'rgba(46,49,69,0.5)' }}
      }}
