// 2. Drawdown Chart
new Chart(document.getElementById('drawdownChart'), {{
  type: 'line',
  data: {{
    labels: {json.dumps(dd_dates)},
    datasets: [{{
      label: 'Drawdown %',
      data: {json.dumps(dd_values)},
      borderColor: '#ef4444',
      backgroundColor: 'rgba(239,68,68,0.12)',
      fill: true,
      borderWidth: 1.5,
      pointRadius: 0,
      tension: 0.1,
    }}]
  }},
  options: {{
    responsive: true,
    interaction: {{ mode: 'index', intersect: false }},
    plugins: {{
      legend: {{ display: false }},
      tooltip: {{
        callbacks: {{
          label: ctx => ctx.parsed.y.toFixed(1) + '%'
        }}
      }}
    }},
    scales: {{
      x: {{
        ticks: {{ maxTicksLimit: 12, maxRotation: 0 }},
        grid: {{ display: false }}
      }},
      y: {{
        ticks: {{ callback: v => v + '%' }},
        grid: {{ color: 'rgba(46,49,69,0.5)' }}
      }}
    }}
  }}
}});

// 3. Volume Chart
new Chart(document.getElementById('volumeChart'), {{
  type: 'bar',
  data: {{
    labels: {json.dumps(vol_dates)},
    datasets: [{{
      label: 'Avg Monthly Volume',
      data: {json.dumps(vol_values)},
      backgroundColor: 'rgba(99,102,241,0.4)',
      borderColor: '#6366f1',
      borderWidth: 0,
      borderRadius: 2,
    }}]
  }},
  options: {{
    responsive: true,
    interaction: {{ mode: 'index', intersect: false }},
    plugins: {{
      legend: {{ display: false }},
      tooltip: {{
        callbacks: {{
          label: ctx => ctx.parsed.y.toLocaleString() + ' shares'
        }}
      }}
    }},
    scales: {{
      x: {{
        ticks: {{ maxTicksLimit: 12, maxRotation: 0 }},
        grid: {{ display: false }}
      }},
      y: {{
        ticks: {{ callback: v => (v/1e6).toFixed(1) + 'M' }},
        grid: {{ color: 'rgba(46,49,69,0.5)' }}
      }}
    }}
  }}
}});

// 4. CAGR Sub-Period Chart
new Chart(document.getElementById('cagrChart'), {{
  type: 'bar',
  data: {{
    labels: {json.dumps([s['label'] for s in sub_cagrs])},
    datasets: [{{
      label: 'CAGR %',
      data: {json.dumps([s['cagr_pct'] for s in sub_cagrs])},
      backgroundColor: {json.dumps(['rgba(34,197,94,0.6)' if s['cagr_pct'] >= 0 else 'rgba(239,68,68,0.6)' for s in sub_cagrs])},
      borderColor: {json.dumps(['#22c55e' if s['cagr_pct'] >= 0 else '#ef4444' for s in sub_cagrs])},
      borderWidth: 1,
      borderRadius: 4,
    }}]
  }},
  options: {{
    responsive: true,
    indexAxis: 'y',
    plugins: {{
      legend: {{ display: false }},
      tooltip: {{
        callbacks: {{
          label: ctx => ctx.parsed.x.toFixed(1) + '% CAGR'
        }}
      }}
    }},
    scales: {{
      x: {{
        ticks: {{ callback: v => v + '%' }},
        grid: {{ color: 'rgba(46,49,69,0.5)' }}
      }},
      y: {{
        grid: {{ display: false }}
      }}
    }}
  }}
}});

// 5. Dividend Yield Chart
new Chart(document.getElementById('divYieldChart'), {{
  type: 'line',
  data: {{
    labels: {json.dumps([str(y) for y in div_yield_years])},
    datasets: [{{
      label: 'Dividend Yield %',
      data: {json.dumps(div_yield_vals)},
      borderColor: '#f59e0b',
      backgroundColor: 'rgba(245,158,11,0.1)',
      fill: true,
      borderWidth: 1.5,
      pointRadius: 2,
      pointHoverRadius: 5,
      tension: 0.2,
    }}]
  }},
  options: {{
    responsive: true,
    interaction: {{ mode: 'index', intersect: false }},
    plugins: {{
      legend: {{ display: false }},
      tooltip: {{
        callbacks: {{
          label: ctx => ctx.parsed.y.toFixed(2) + '% yield'
        }}
      }}
    }},
    scales: {{
      x: {{
        ticks: {{ maxTicksLimit: 12, maxRotation: 0 }},
        grid: {{ display: false }}
      }},
      y: {{
        ticks: {{ callback: v => v + '%' }},
        grid: {{ color: 'rgba(46,49,69,0.5)' }}
      }}
    }}
  }}
}});

// 6. Decade Comparison Chart
new Chart(document.getElementById('decadeChart'), {{
  type: 'bar',
  data: {{
    labels: {json.dumps(dec_labels)},
    datasets: [
      {{
        label: 'CAGR %',
        data: {json.dumps(dec_cagr_chart)},
        backgroundColor: 'rgba(34,197,94,0.6)',
        borderColor: '#22c55e',
        borderWidth: 1,
        borderRadius: 4,
      }},
      {{
